package main
​
import (
    "fmt"
    "sort"
)
​
func main() {
    var n int
    fmt.Scan(&n)
​
    // 使用 map 去重
    set := make(map[int]bool)
    for i := 0; i < n; i++ {
        var tmp int
        fmt.Scan(&tmp)
        set[tmp] = true
    }
​
    // map 无序，因此收集 key 并排序后输出
    var nums []int
    for k := range set {
        nums = append(nums, k)
    }
    sort.Ints(nums)
​
    for _, num := range nums {
        fmt.Println(num)
    }
}
